import {createStateStore,createRegistry,createRuntime} from '/Users/minholim/dev/minh/viewstem/packages/core/src/api.mjs';
const reactions=[];
for(const kind of ['disposed','foreign']) {
  const store=createStateStore(),cells=store.createScope(),other=createStateStore();
  const owner=kind==='foreign'?other.createScope():store.createScope();
  const watched=cells.registerState('watched',{schema:{type:'number'},initial:0});
  const target=cells.registerState('target',{schema:{type:'number'},initial:9});
  if(kind==='disposed')owner.dispose();
  let error;
  try{store.registerReaction(owner,{watch:[watched],target,value:1});}catch(e){error=e.code;}
  if(kind==='foreign')owner.dispose();
  watched.write(1);reactions.push({kind,error,targetAfterOwnerDisposal:target.read()});
  store.dispose();other.dispose();
}
const integer={type:'integer'};
const functions=[{name:'doubleForRenderer',inputs:[integer],output:integer,run:n=>n*2}];
const resource={kind:'Variable',id:'double',spec:{ports:{n:{kind:'Value',schema:integer,required:true}},expression:'doubleForRenderer(n)'}};
const registry=createRegistry(),runtime=createRuntime({registry,functions});
let rendererPattern;
try{registry.registerResources([resource]);rendererPattern={success:true};}catch(e){rendererPattern={code:e.code,message:e.message};}
const configured=createRegistry({functions});configured.registerResources([resource]);runtime.dispose();
console.log(JSON.stringify({reactions,functions:{rendererPattern,controlRegistered:configured.get('Variable','double').id}},null,2));

